DECLARE @t int = (SELECT TOP 1 Id FROM plat.Tenant ORDER BY Id);
IF NOT EXISTS (SELECT 1 FROM plat.Org WHERE TenantId=@t)
BEGIN
    DECLARE @hq int = SCOPE_IDENTITY();
    UPDATE plat.Org SET [Path] = CASE WHEN ParentId IS NULL THEN '/' + CAST(Id AS varchar) + '/'
        ELSE '/' + CAST(ParentId AS varchar) + '/' + CAST(Id AS varchar) + '/' END;
END
GO
DECLARE @t int = (SELECT TOP 1 Id FROM plat.Tenant ORDER BY Id);
IF NOT EXISTS (SELECT 1 FROM plat.Employee)
SELECT @t,'E001',N'系统管理员',(SELECT TOP 1 Id FROM plat.Org WHERE Code='0101'),N'信息管理员','13800000000',0;
IF NOT EXISTS (SELECT 1 FROM plat.[User])
SELECT @t,'admin','AQAAAAIAAYagAAAAEPlaceholderHashForDemo=','s1',
       (SELECT TOP 1 Id FROM plat.Employee WHERE Code='E001'),N'系统管理员',1,
       (SELECT TOP 1 Id FROM plat.Org WHERE Code='01');
IF NOT EXISTS (SELECT 1 FROM plat.Role)
IF NOT EXISTS (SELECT 1 FROM plat.UserRole)
SELECT @t,(SELECT TOP 1 Id FROM plat.[User] WHERE UserName='admin'),(SELECT Id FROM plat.Role WHERE Code='SYSADMIN');
GO
