/* ============ 权限资源与授权 ============ */
DECLARE @t int = (SELECT TOP 1 Id FROM plat.Tenant ORDER BY Id);
SELECT @t,'MOD:' + m.Code,1,m.Name,NULL,m.Id FROM plat.Module m WHERE m.TenantId=@t;
SELECT @t,'FUN:' + m.Code + '.' + f.Code,2,m.Name + '/' + f.Name,'MOD:' + m.Code,m.Id,f.Id
FROM plat.ModuleFunction f JOIN plat.Module m ON m.Id = f.ModuleId WHERE m.TenantId=@t;
GO
DECLARE @t int = (SELECT TOP 1 Id FROM plat.Tenant ORDER BY Id);
DECLARE @role bigint = (SELECT Id FROM plat.Role WHERE TenantId=@t AND Code='SYSADMIN');
SELECT @t,@role,p.Id,1,1,1,1,1,1,
       CASE WHEN p.ResourceType=1 THEN 1 ELSE 2 END
FROM plat.Permission p WHERE p.TenantId=@t;
GO
/* ============ 菜单（三级：域/二级/菜单） ============ */
DECLARE @t int = (SELECT TOP 1 Id FROM plat.Tenant ORDER BY Id);
DELETE FROM plat.MenuTerminal;
DELETE FROM plat.Menu;
SELECT @t,NULL,m.Code,m.Name,m.Id,1,'/' + m.Code,m.Icon,m.Sort,1
FROM plat.Module m WHERE m.TenantId=@t AND m.[Level]=1;
GO
