/* 终端可见性：按域映射 */

DECLARE @t int = (SELECT TOP 1 Id FROM plat.Tenant ORDER BY Id);
SELECT m.Id,1,1,m.Sort FROM plat.Menu m WHERE m.TenantId=@t;
SELECT m.Id,2,1,m.Sort FROM plat.Menu m WHERE m.TenantId=@t AND (m.Code LIKE '04%');
SELECT m.Id,3,1,m.Sort FROM plat.Menu m WHERE m.TenantId=@t AND (m.Code LIKE '07%');
SELECT m.Id,4,1,m.Sort FROM plat.Menu m WHERE m.TenantId=@t AND (m.Code LIKE '03%' OR m.Code LIKE '10%');
SELECT m.Id,5,1,m.Sort FROM plat.Menu m WHERE m.TenantId=@t AND (m.Code LIKE '06%' OR m.Code LIKE '05%');
SELECT m.Id,6,1,m.Sort FROM plat.Menu m WHERE m.TenantId=@t AND (m.Code LIKE '0206%' OR m.Code LIKE '0306%' OR m.Code LIKE '0108%');
GO
